      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉકેલ/જવાબ:</strong> માણસ પ્રાણીઓના અંગો મેળવવા તેમનો શિકાર કરે છે અને જંગલો કાપીને તેમના રહેઠાણ છીનવી લે છે.</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: માણસ = શિકારી + જંગલ વિનાશક.</p></div>"
